import {readFile,writeFile} from 'node:fs/promises';
import {resolve} from 'node:path';
import {createHash} from 'node:crypto';
import {chromium} from 'playwright';
import {captureClientPage,startClientPageReplay} from '../../framework-comparison/src/client-page-replay.mjs';
import {startComparisonServer} from '../../framework-comparison/src/server.mjs';
import {balancedRoundOrder} from '../../framework-comparison/src/balanced-round-order.mjs';
import {summarizePercentiles} from '../../framework-comparison/src/percentile-summary.mjs';
import {captureHeapComposition} from '../../framework-comparison/src/browser-heap-snapshot.mjs';
import {measureBrowserSample} from './browser-sample.mjs';
const population=Number(process.env.AUDIT_POPULATION??0);
const rate=Number(process.env.AUDIT_CPU_RATE??1);
const variants=['baseline','terser'];
const live=await import('../../framework-comparison/src/e2e-server.mjs');
let service,browser;const servers=[];const evidence={cpuRate:rate,population,sharedPc:false,hostActivity:"User confirmed browser closed before this capture",createdAt:new Date().toISOString(),orders:[],variants:{}};
try{
 const reset=await fetch('http://127.0.0.1:4310/__benchmark/reset',{method:'POST',headers:{'content-type':'application/json','x-benchmark-control':'fixture-reset'},body:'{}'});if(!reset.ok)throw Error('reset');
 const capture=await captureClientPage({id:'exact',url:'http://127.0.0.1:4401',directory:resolve('framework-comparison/participants/exact/dist')});
 await live.close();service=await startComparisonServer();browser=await chromium.launch();
 for(const [i,id] of variants.entries()){
 const bytes=await readFile(`.tmp/framework-audit/${id}.js`);
 const resources=new Map(capture.resources);const jsPath=[...resources.keys()].find(p=>p.endsWith('.js'));
 resources.set(jsPath,{...resources.get(jsPath),body:bytes});
 const url=`http://127.0.0.1:${4501+i}`;
 servers.push(await startClientPageReplay({...capture,id,url,resources}));
 evidence.variants[id]={url,bytes:bytes.length,sha256:createHash('sha256').update(bytes).digest('hex'),samples:[],heaps:[]};
 }
 for(let round=-2;round<60;round++){
 const order=balancedRoundOrder(variants,round+2,population);if(round>=0)evidence.orders.push(order);
 for(const id of order){const sample=await measureBrowserSample(browser,{id,url:evidence.variants[id].url});if(round>=0)evidence.variants[id].samples.push(sample);}
 if(round%15===0)console.log('Interaction round',round+1);
 }
 for(let round=0;round<9;round++)for(const id of balancedRoundOrder(variants,round,population)){
 await fetch('http://127.0.0.1:4310/__benchmark/reset',{method:'POST',headers:{'content-type':'application/json','x-benchmark-control':'fixture-reset'},body:'{}'});
 const context=await browser.newContext();try{
 const page=await context.newPage();const cdp=await context.newCDPSession(page);await cdp.send('Network.enable');await cdp.send('Network.setCacheDisabled',{cacheDisabled:true});
 await page.goto(`${evidence.variants[id].url}/incidents/inc-100`);await page.locator('.connection').getByText('Live service',{exact:true}).waitFor();await page.getByRole('button',{name:'Claim incident'}).click();await page.getByText('Version 2',{exact:true}).waitFor();await cdp.send('HeapProfiler.collectGarbage');evidence.variants[id].heaps.push(await captureHeapComposition(cdp));
 }finally{await context.close();}
 }
 evidence.replay=servers.map(s=>s.evidence());
 for(const v of Object.values(evidence.variants))v.summary=Object.fromEntries(['optimisticFeedbackMs','settlementMs','heapBytes'].map(key=>[key,summarizePercentiles(v.samples.map(s=>s[key]))]).concat([['navigationMs',summarizePercentiles(v.samples.map(s=>s.navigation.durationMs))]]));
 await writeFile(`\.tmp/framework-audit/quiet-${rate}x-${population}.json`,JSON.stringify(evidence,null,2));
 console.log(Object.fromEntries(Object.entries(evidence.variants).map(([id,v])=>[id,v.summary])));
}finally{await browser?.close();await Promise.all(servers.map(s=>s.close()));await service?.close();await live.close();}

