import {readFile,writeFile} from 'node:fs/promises';
const evidence={createdAt:new Date().toISOString(),hostActivity:'User confirmed browser closed; no concurrent builds, tests, or profiling during timed samples.',rates:{}};
let seed=194827;
const random=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};
const average=a=>a.reduce((s,x)=>s+x,0)/a.length;
const metrics={navigation:s=>s.navigation.durationMs,optimistic:s=>s.optimisticFeedbackMs,settlement:s=>s.settlementMs,heap:s=>s.heapBytes};
for(const rate of [1,6]){
 const populations=await Promise.all([0,1].map(async p=>JSON.parse(await readFile(`.tmp/framework-audit/quiet-${rate}x-${p}.json`))));
 const result={populations,metrics:{}};
 for(const [name,read]of Object.entries(metrics)){
 const before=populations.flatMap(p=>p.variants.baseline.samples.map(read));
 const after=populations.flatMap(p=>p.variants.terser.samples.map(read));
 const deltas=populations.map(p=>p.variants.baseline.samples.map((s,i)=>read(p.variants.terser.samples[i])-read(s)));
 const boot=[];
 for(let sample=0;sample<10000;sample++){
  let sum=0,count=0;
  for(const values of deltas)for(let block=0;block<values.length/5;block++){
   const start=Math.floor(random()*(values.length/5))*5;
   for(let j=0;j<5;j++){sum+=values[start+j];count++;}
  }
  boot.push(sum/count);
 }
 boot.sort((a,b)=>a-b);
 result.metrics[name]={baseline:average(before),candidate:average(after),delta:average(after)-average(before),percent:(average(after)/average(before)-1)*100,pairedBlockBootstrap95:[boot[249],boot[9749]],populationDeltas:deltas.map(average)};
 }
 evidence.rates[rate]=result;
 console.log(rate,result.metrics);
}
evidence.sources={runner:await readFile('.tmp/framework-audit/client-quiet.mjs','utf8'),sample:await readFile('.tmp/framework-audit/browser-sample.mjs','utf8'),analysis:await readFile(import.meta.filename,'utf8')};
await writeFile('docs/performance-baselines/framework-audit-2026-09-07-quiet.json',JSON.stringify(evidence,null,2));
